"""Add the ten-value recurrent report and gallery without rewriting old pages."""
from pathlib import Path
import json,shutil,hashlib
import numpy as np
from huggingface_hub import HfApi,hf_hub_download
R=Path(__file__).resolve().parent;D=R/'data/report-public';D.mkdir(exist_ok=True);(D/'cone46').mkdir(exist_ok=True);(D/'full-sequence').mkdir(exist_ok=True)
proof=json.loads((R/'results03/collected.json').read_text());assert proof['passed']
analysis=json.loads((R/'data/analysis/integral-comparison.json').read_text());prior=json.loads((R.parent/'39_long_window_continuation/data/analysis/integral-comparison.json').read_text())
assert len(analysis['records'])==len(prior['records'])==208
for a,b in zip(analysis['records'],prior['records']):assert a['id']==b['id'] and a['truth']==b['truth'] and a['time']==b['time']
report=json.loads((R/'data/pool03-results/report.json').read_text());fold=report['folds'][0];test=report['tests'][0]['metrics']['rollout'];assert fold['selected_epoch']==134 and fold['epochs']==164
api=HfApi();repo='wdavies/fire-reports';rev=api.repo_info(repo,repo_type='space').sha
old={n:Path(hf_hub_download(repo,n,repo_type='space',revision=rev)).read_text() for n in ['index.html','full-sequence/index.html','full-sequence/gallery.html']}
for n,s in old.items():(D/('parent-'+n.replace('/','__'))).write_text(s)
rows=''.join(f'<tr><th>{label}</th><td>{prior["aggregate_percent"][i]:.4f}%</td><td>{analysis["aggregate_percent"][i]:.4f}%</td></tr>' for i,label in enumerate(['Water','Dry fuel','Gas release','Heating index']))
table='<table><tr><th>Four-state test integral error</th><th>39 long-window continuation</th><th>46 ten-value recurrent</th></tr>'+rows+f'<tr><th>Mean</th><td>{np.mean(prior["aggregate_percent"]):.4f}%</td><td>{np.mean(analysis["aggregate_percent"]):.4f}%</td></tr></table>'
cone_rows=''.join(f'<tr><th>{n}</th><td>{v:.3f} {u}</td></tr>' for n,u,v in zip(['Pivot height','Tilt','Length','Radius','Peak temperature'],['m','degrees','m','m','°C'],test['cone_active_MAE_by_parameter']))
css='body{font:17px/1.6 system-ui;color:#182637;background:#f3f5f8;margin:0}main{max-width:1100px;margin:auto;padding:32px 24px}h1{line-height:1.2}table{border-collapse:collapse;width:100%;background:white}th,td{padding:10px;text-align:left;border-bottom:1px solid #dce3eb}img{width:100%}a{color:#205bb0}'
body=f'''<nav><a href="../index.html">All reports</a> · <a href="../full-sequence/cone46-r0.html">208-history five-chart gallery</a></nav>
<h1>Eight history steps, ten recurrent values</h1><p>Experiment 46 · rotation 0 · selected epoch 134 of 164 · completed 2 November 2026</p>
<p>The selected model's four-state test integral error is <strong>5.0073%</strong>, versus <strong>4.7861%</strong> for experiment 39. Water is worse; fuel, gas and heating are slightly better. This is not a uniform improvement. The new model also predicts and feeds back cone presence and five cone values.</p>
<h2>Matched four-state results</h2><p>Exact same 208 test histories, 204 configurations, times and simulation values. Error is the exact integral of absolute piecewise-linear error divided by duration times the reference feature range; replicas average within each configuration, then configurations have equal weight.</p>{table}
<h2>Cone results</h2><p>Mean absolute errors while the reference cone is present, equally weighted by configuration. Geometry errors remain scored even if the model predicts absence.</p><table>{cone_rows}</table>
<p>Presence accuracy: {100*test['cone_presence_accuracy']:.2f}%; missed reference-active fraction: {100*test['cone_missed_active_fraction']:.2f}%; false-active fraction among reference-inactive endpoints: {100*test['cone_false_active_fraction']:.2f}%. Test cone parameter loss: {test['cone_parameters_loss']:.5f}; presence BCE: {test['cone_presence_bce']:.5f}; joint selection score: {test['joint_selection_objective']:.5f}.</p>
<h2>Model, curriculum and selection</h2><p>Fresh seed 3516, no inherited weights from experiment 39 or the stopped experiment 45. Each of eight historical timesteps contains water, fuel, gas, heating, presence, pivot, tilt, length, radius and peak temperature. All ten predictions feed the next history. Flattened 80 history values plus nine external inputs enter one GRU64, shared Linear64 + SiLU, no dropout: 34,765 parameters. Teacher truth is available only through the forecast origin; the detached prefix contains no future truth.</p>
<p>Windows 1/8/16/32/64/90 start at epochs 1/21/41/61/110/130. Full90 spans approximately 180 seconds and has one origin/history and seven optimizer updates/epoch, versus 27 origins/history and 176 updates at64. Minimum160, maximum400, patience30. Training stopped by {fold['stop_reason']}; validation selected epoch134 before any test evaluation. Experiment39 continued a selected prior checkpoint, whereas46 began fresh and selects on a joint cone/state objective, so this comparison does not isolate the effect of cone feedback.</p>
<p>Training loss = state integral +0.1 old gate BCE +0.1 presence BCE +mean five-parameter SmoothL1(beta0.1), using fixed scales12m/90degrees/24m/16m/1500°C. Cone regression uses elapsed-time weights and reference-active duration, masked by truth; all-inactive windows contribute zero. Presence is scored at all endpoints. Selection excludes old gate BCE. Initial loss weights are experimental.</p>
<h2>Learning curves</h2><img src="learning-curve.png" alt="All164 completed epochs with separate state, cone, presence and joint losses"><p>No smoothing. These are full autonomous sequence evaluations, independent of the current training-window length. The final epoch is not the selected checkpoint.</p>
<h2>Five-chart gallery</h2><p><a href="../full-sequence/cone46-r0.html">Open all208 histories, three cases per page</a>. The original four plots retain their controls and rubric. The fifth shows cone length (left axis, metres) and peak temperature (right axis, °C), reference solid and prediction dashed, with gaps when absent (prediction probability below0.5). The presence threshold is display-only; soft probabilities remain in recurrent feedback. This fifth chart does not reveal pivot, tilt or radius errors; geometric views/storyboards are needed for those.</p>
<h2>Recovery and preservation</h2><p>Pool01 was Spot-preempted after116 completed epochs. Pool02 was preempted before its worker started. Pool03 resumed117 from the complete model/optimizer/RNG/history checkpoint with unchanged input file hashes; exact first-update replay and all seven cloud checks passed. No completed epoch was retrained. All164 checkpoints, selected-model outputs and selection-before-test timing were verified. The original epoch1 replay proof was copied, not rerun as a fresh epoch.</p>
<h2>Limits</h2><p>This is a historically examined dataset, not pristine confirmation. The cone labels are broad envelopes fitted to gas cells above50°C, not physical flames, ignition boundaries or heat flux. Training-label median purity is about20.5% at95% hot-cell recall;86.8% of fitted apexes are at ground level. Their fixed downwind plane and sampled angle/apex grid constrain geometry. Peak temperature is instantaneous at approximately2-second saved endpoints, not the interval maximum or received heat.</p>
<p>Source simulations use generic4–10m vegetation crowns,0.5m mesh and a24×16×16m observed crop, with imposed1500°C ignition for20s included. No buildings, trunks or embers are modeled. Gas is vegetation fuel-gas release; heating is a surface-heating index, not stored energy. These results do not validate realistic species, building ignition or property-scale fire risk. No hardware causal claim is made.</p>
<p><a href="https://github.com/davies-w/wildfire3d/tree/codex/ignition-surrogate-pilot/experiments/46_cone_recurrent10">Source and DVC records</a></p>'''
(D/'cone46/index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ten-value recurrent cone model</title><style>'+css+'</style><main>'+body+'</main></html>')
shutil.copy2(R/'data/progress-public/learning-curve.png',D/'cone46/learning-curve.png');shutil.copy2(R/'data/public/gated.html',D/'full-sequence/cone46-r0.html');shutil.copy2(R/'data/analysis/integral-comparison.json',D/'full-sequence/cone46-r0-values.json')
card='<a class="card" href="cone46/index.html" target="_blank" rel="noopener noreferrer"><span class="tag">Experiment46 · completed</span><h2>Ten-value recurrent cone model →</h2><p>Fresh GRU64 with all ten states fed back. Matched results, cone errors and five-chart gallery.</p></a>'
assert 'cone46/index.html' not in old['index.html'];new=old['index.html'].replace('<div class="cards">','<div class="cards">'+card,1);assert new.replace(card,'',1)==old['index.html'];(D/'index.html').write_text(new)
for name in ['full-sequence/index.html','full-sequence/gallery.html']:
 addition='<section><h2>Ten-value recurrent cone model</h2><p><a href="cone46-r0.html">Rotation0 · selected epoch134 · five-chart gallery</a> · <a href="../cone46/index.html">Results and limitations</a></p>'+(table if name.endswith('index.html') else '')+'</section>'
 assert '</main>' in old[name];new=old[name].replace('</main>',addition+'</main>',1);assert new.replace(addition,'',1)==old[name];(D/name).write_text(new)
(R/'results03/report-build.json').write_text(json.dumps(dict(passed=True,parent_revision=rev,all_previous_content_preserved=True,matched_test_histories=208,files=7),indent=2)+'\n')
print('Built additive report, index card and five-chart gallery')
